// Tarjan's Bridge Finding - most commonly asked in interviews
function findBridges(n, edges) {
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    adj[u].push(v);
    adj[v].push(u);
  }

  const disc = new Array(n).fill(-1);
  const low = new Array(n).fill(-1);
  const bridges = [];
  let timer = 0;

  function dfs(u, parent) {
    disc[u] = low[u] = timer++;

    for (const v of adj[u]) {
      // skip the edge back to parent (undirected graph)
      if (v === parent) continue;

      if (disc[v] === -1) {
        // tree edge - recurse
        dfs(v, u);
        // pull up the lowest reachable from v's subtree
        low[u] = Math.min(low[u], low[v]);
        // bridge condition: v's subtree can't reach u or above
        if (low[v] > disc[u]) {
          bridges.push([u, v]);
        }
      } else {
        // back edge - update low directly from disc[v]
        low[u] = Math.min(low[u], disc[v]);
      }
    }
  }

  // handle disconnected graphs
  for (let i = 0; i < n; i++) {
    if (disc[i] === -1) dfs(i, -1);
  }

  return bridges;
}
